 const ceramic=new THREE.MeshStandardMaterial({color:0xe0d4b7,map:grain,bumpMap:grain,bumpScale:.05,roughness:.94});
 const profile=[[0,.17],[1.02,.17],[1.17,.28],[1.36,1.18],[1.45,2.42],[1.42,2.60],[1.30,2.63],[1.28,2.48],[1.22,1.32],[1.00,.36],[0,.36]].map(p=>new THREE.Vector2(...p));
