 stones.forEach(([x,y,z,sx,sy,sz],j)=>{const geo=new THREE.IcosahedronGeometry(1,2),p=geo.attributes.position;for(let i=0;i<p.count;i++){const n=.82+rnd(i+j*709)*.3;p.setXYZ(i,p.getX(i)*n,p.getY(i)*n,p.getZ(i)*n)}geo.computeVertexNormals();const rock=mesh(plant,geo,lava,x,y,z);rock.scale.set(sx,sy,sz);rock.rotation.set(.1*j,.6*j,-.1*j)});
 const barkMap=barkTexture(texture),wood=new THREE.MeshStandardMaterial({color:0x5b3827,map:barkMap,bumpMap:barkMap,bumpScale:.08,roughness:.97});
 tube(plant,[[.23,.64,-.23],[.22,1.7,-.19],[-.45,2.7,-.28],[-1.0,3.64,-.20]],.14,wood,30,.54);
 tube(plant,[[-.38,2.53,-.25],[-.82,2.38,-.11],[-1.24,2.82,.02],[-1.31,3.19,.12]],.047,wood,23,.7);
