 const moss=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1,1),new THREE.MeshStandardMaterial({color:0x687a2d,roughness:1}),550),dummy=new THREE.Object3D();for(let i=0;i<550;i++){let x,y,z;const a=rnd(i+11)*6.283,r=Math.sqrt(rnd(i+78));if(i<320){x=Math.cos(a)*r*.98;z=Math.sin(a)*r*.98;y=.59+rnd(i+402)*.09}else{const center=stones[(i%4)];x=center[0]+Math.cos(a)*r*center[3];z=center[2]+Math.sin(a)*r*center[5];y=center[1]+center[4]*Math.sqrt(1-r*r)*.92}dummy.position.set(x,y,z);dummy.scale.set(.025+rnd(i+22)*.075,.025+rnd(i+88)*.09,.025+rnd(i+55)*.05);dummy.rotation.set(rnd(i)*2,rnd(i+2)*6,rnd(i+31));dummy.updateMatrix();moss.setMatrixAt(i,dummy.matrix);moss.setColorAt(i,new THREE.Color().setHSL(.19+rnd(i+45)*.07,.36+rnd(i+65)*.25,.18+rnd(i+76)*.15))}plant.add(moss);
 const leafMap=texture(128,256,g=>{g.fillStyle='#739345';g.fillRect(0,0,128,256);g.fillStyle='#cee09b';g.fillRect(63,0,2,256);for(let j=0;j<18;j++){g.strokeStyle='#35552130';g.lineWidth=1;g.beginPath();g.moveTo(64,j*15);g.lineTo(j%2?123:4,j*15-25);g.stroke()}});
 const green=new THREE.MeshPhysicalMaterial({color:0x91b954,map:leafMap,bumpMap:leafMap,bumpScale:.005,roughness:.57,clearcoat:.2,side:THREE.DoubleSide}),silver=new THREE.MeshStandardMaterial({color:0xa5b9a1,roughness:.78,side:THREE.DoubleSide}),stem=new THREE.MeshStandardMaterial({color:0x4c6227,roughness:.85});
